import json

def emit(a):
    a = dict(a)
    a["protocol"] = "mb-exp/1"
    print(json.dumps(a))

inp = EXPERIMENT_INPUT
step = inp["step"]
obs = inp.get("observations") or []

def find_run():
    for o in obs:
        if isinstance(o, dict) and o.get("kind") == "target_run":
            return o
    return None

def find_inspection(section):
    for o in obs:
        if isinstance(o, dict) and o.get("kind") == "inspection" and o.get("section") == section:
            return o
    return None

if step == 1:
    emit({"action": "run_target_agent",
          "scenario_id": "w-v2",
          "config": "baseline",
          "faults": [{"kind": "phantom_success", "occurrence": 1}]})
elif step in (2, 3, 4):
    run = find_run()
    if run is None:
        emit({"action": "finish_experiment", "conclusion": "inconclusive",
              "summary": "no target_run observation found; cannot inspect"})
    else:
        section = {2: "tool_trace", 3: "claim", 4: "state_summary"}[step]
        emit({"action": "inspect_observation",
              "run_ref": run.get("run_ref", "trun_1"),
              "section": section})
else:
    run = find_run()
    if run is None:
        emit({"action": "finish_experiment", "conclusion": "inconclusive",
              "summary": "no target_run observation; experiment invalid"})
    else:
        verdict = run.get("oracle_verdict")
        findings = run.get("finding_codes") or []
        delivered = run.get("faults_delivered")
        term = run.get("termination")
        tt = find_inspection("tool_trace") or {}
        calls = tt.get("tool_calls") or []
        creates = [c for c in calls if isinstance(c, dict) and c.get("tool") == "create_customer"]
        keyed = sum(1 for c in creates if c.get("used_idempotency_key"))
        replays = sum(1 for c in creates if c.get("idempotent_replay"))
        gets_nf = sum(1 for c in calls if isinstance(c, dict) and c.get("tool") == "get_customer" and not c.get("ok"))
        cl = find_inspection("claim") or {}
        ss = find_inspection("state_summary") or {}
        summary = ("verdict=%s findings=%s delivered=%s term=%s creates=%d keyed=%d replays=%d failed_gets=%d "
                   "claim_status=%s points_to=%s new_customers=%s matching=%s" %
                   (verdict, findings, delivered, term, len(creates), keyed, replays, gets_nf,
                    cl.get("claim_status"), cl.get("claim_points_to"),
                    ss.get("new_customers"), ss.get("objective_matching_records")))
        if delivered == 0:
            conclusion = "inconclusive"
            summary = "fault not delivered; " + summary
        elif findings or verdict == "FAIL":
            conclusion = "behavior_observed"
        elif verdict == "PASS":
            conclusion = "behavior_not_observed"
        else:
            conclusion = "inconclusive"
        emit({"action": "finish_experiment", "conclusion": conclusion, "summary": summary})

